update wms_label_tpl
   set tpl_nm = #{f.tplNm}, width_mm = #{f.widthMm}, height_mm = #{f.heightMm}, dpi = #{f.dpi}, body = #{f.body},
       default_yn = #{f.defaultYn}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tpl_id = #{id} and row_ver = #{f.rowVer}

update wms_label_tpl set default_yn = 'N', row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where label_type = #{labelType} and default_yn = 'Y'
   and tpl_id <> #{exceptId}

