where j.requested_at >= #{q.fromAt} and j.requested_at < #{q.toAt}
and j.label_type = #{q.labelType}
and o.status = #{q.status}
and  = #{q.printState}
and j.biz_key ilike #{q.bizKeyLike} escape '\'
and j.plant_cd = #{q.plantCd}

